const ticket = {
  id: 7,
  title: 'Błąd eksportu',
  description: 'Plik CSV jest pusty.',
  status: 'OPEN',
  priority: 'HIGH',
  assignee: null,
  createdAt: '2026-10-01T09:30:00Z',
  tags: ['export'],
};

const ticket = { assignee: null };
const assigneeLabel = ticket.assignee ?? 'Nieprzypisane';
console.log(assigneeLabel); // Nieprzypisane
const assignedTicket = { assignee: 'anna' };
console.log(assignedTicket.assignee ?? 'Nieprzypisane'); // anna

const tickets = [
  { id: 1, status: 'OPEN' },
  { id: 2, status: 'IN_PROGRESS' },
  { id: 3, status: 'CLOSED' },
];
console.log(tickets.length); // 3

const tickets = [{ id: 1, status: 'OPEN' }, { id: 2, status: 'CLOSED' }, { id: 3, status: 'OPEN' }];
const openCount = tickets.filter(ticket => ticket.status === 'OPEN').length;
console.log(openCount); // 2

const tickets = [{ id: 1, priority: 'HIGH' }, { id: 2, priority: 'LOW' }, { id: 3, priority: 'CRITICAL' }];
const urgent = tickets.filter(ticket => ticket.priority === 'HIGH' || ticket.priority === 'CRITICAL');
console.log(urgent.map(ticket => ticket.id)); // [1, 3]

const tickets = [{ id: 1, assignee: 'anna' }, { id: 2, assignee: null }, { id: 3, assignee: 'jan' }];
const currentUser = 'anna';
const mine = tickets.filter(ticket => ticket.assignee === currentUser);
console.log(mine); // [{ id: 1, assignee: 'anna' }]

