type TicketStatus = 'OPEN' | 'IN_PROGRESS' | 'CLOSED';
type TicketPriority = 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
type Ticket = {
  id: number;
  title: string;
  description: string;
  status: TicketStatus;
  priority: TicketPriority;
  assignee: string | null;
  createdAt: string;
  tags: string[];
};

const tickets = [
  { id: 1, status: 'OPEN', priority: 'HIGH', assignee: 'anna' },
  { id: 2, status: 'CLOSED', priority: 'LOW', assignee: null },
  { id: 3, status: 'IN_PROGRESS', priority: 'CRITICAL', assignee: 'anna' },
];
const currentUser = 'anna';
const stats = {
  total: tickets.length,
  open: tickets.filter(t => t.status === 'OPEN').length,
  urgent: tickets.filter(t => t.priority === 'HIGH' || t.priority === 'CRITICAL').length,
  mine: tickets.filter(t => t.assignee === currentUser).length,
};
console.log(stats); // { total: 3, open: 1, urgent: 2, mine: 2 }
